// Three distinct failures, three distinct messages. A single
// "UAT is down" alert would make the common case (stale image) look
// like the rare case (server dead) and waste the founder's attention.
const item = $input.first().json;

// The HTTP node's error output carries `error`; a 404 lands here too,
// and a 404 on /api/version is itself the signal: that endpoint shipped
// on 2026-08-10, so an image without it predates that commit.
if (item.error || !item.commit) {
  const is404 = String(item.error || '').includes('404');
  return [{ json: {
    alert: true,
    text: is404
      ? '⚠️ Certifine UAT: /api/version 返 404 — 個 image 舊過 2026-08-10，即係 deploy 未生效。'
      : '⚠️ Certifine UAT API (api-uat:4000) 冇回應，可能死咗。',
  }}];
}

// An unstamped image means someone built outside ci/ci-run.sh. It is not
// an outage, but it means the next deploy check cannot prove anything.
if (item.commit === 'unknown' || item.commit === 'dev') {
  return [{ json: {
    alert: true,
    text: `⚠️ Certifine UAT 行緊未蓋章嘅 build（commit=${item.commit}）。用 ./ci.sh 或 ci/ci-run.sh dockerbuild 重 build 先驗得到 deploy。`,
  }}];
}

// Healthy: stay silent. An alert that fires when nothing is wrong is how
// people learn to ignore alerts.
return [{ json: { alert: false, commit: item.commit, builtAt: item.builtAt } }];
